const directoryState = { query: '', type: 'all', mentors: false };
let wallFilter = 'all';
let wallDeepLinkHandled = false;
globalThis.addEventListener?.('hashchange', () => { if (!globalThis.location?.hash?.includes('wall=1')) wallDeepLinkHandled = false; });
const postCategories = { introduction: 'Introductions', question: 'Questions', moment: 'Shared moments' };
let profileTab = 'overview';
const types = { student: 'Student', alumni: 'Alumni', community: 'Community' };

function state(ctx) { return ctx.store.getState(); }
function esc(ctx, value) { return ctx.esc(String(value ?? '')); }
function list(value) { return Array.isArray(value) ? value : []; }
function memberType(member) { return String(member.type || 'community').toLowerCase(); }
function typeLabel(member) { return types[memberType(member)] || 'Community'; }
function initials(name) { return String(name || 'Member').trim().split(/\s+/).slice(0, 2).map(s => s[0]).join('').toUpperCase(); }
function avatar(ctx, member, large = false) {
  const color = [...String(member.id || member.name)].reduce((n, c) => n + c.charCodeAt(0), 0) % 5;
  return `<div class="avatar member-avatar avatar-tone-${color}${large ? ' avatar-large' : ''}" aria-hidden="true"><span>${esc(ctx, initials(member.name))}</span><i></i><b></b></div>`;
}
function publicMembers(ctx) {
  const s = state(ctx);
  const members = list(s.members).filter(m => m.id !== s.profile?.id);
  if (s.profile) members.unshift(s.profile);
  return members.filter(m => m.directoryVisible === true && m.status === 'approved');
}
function memberCard(ctx, m) {
  const details = [m.university, m.employer, m.jobTitle, m.city].filter(Boolean).join(' · ');
  const index = [m.name, m.nameBn, m.university, m.major, m.employer, m.jobTitle, m.city, ...list(m.skills)].join(' ').toLowerCase();
  return `<article class="member-card community-member-card" data-member-type="${esc(ctx, memberType(m))}" data-member-mentor="${m.mentor ? 'true' : 'false'}" data-member-search="${esc(ctx, index)}">
    <div class="member-card-top">${avatar(ctx, m)}<span class="badge badge-soft">${typeLabel(m)}</span></div>
    <h3><a href="#/members/${encodeURIComponent(m.id)}">${esc(ctx, m.name)}</a></h3>
    ${m.nameBn ? `<p class="member-bangla" lang="bn">${esc(ctx, m.nameBn)}</p>` : ''}
    <p class="member-role">${esc(ctx, m.jobTitle || m.major || typeLabel(m))}</p>
    <p class="member-meta">${esc(ctx, details || 'Part of our community')}</p>
    <div class="member-skills">${list(m.skills).slice(0, 3).map(skill => `<span>${esc(ctx, skill)}</span>`).join('')}</div>
    <div class="member-card-footer"><span class="mentor-label">${m.mentor ? '<span aria-hidden="true">↗</span> Open to mentoring' : 'Here to connect'}</span><span class="sample-label">Demo profile</span></div>
  </article>`;
}

function noteDate(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : date.toLocaleDateString('en-GB', {day: 'numeric', month: 'short'}); }
function wallPost(ctx, post) {
  const profile = state(ctx).profile, loved = list(post.hearts).includes(profile?.id), own = profile?.id === post.userId;
  return `<article class="cw-note cw-note-${esc(ctx, post.category)}" data-wall-category="${esc(ctx, post.category)}" data-post-id="${esc(ctx, post.id)}">
    <div class="cw-note-header"><span class="cw-pin" aria-hidden="true"></span><span class="cw-category">${postCategories[post.category] || 'Community note'}</span><time datetime="${esc(ctx, post.createdAt)}">${esc(ctx, noteDate(post.createdAt))}</time></div>
    <p class="cw-note-body">${esc(ctx, post.body)}</p>
    <div class="cw-author"><span aria-hidden="true">${esc(ctx, initials(post.name))}</span><div><strong>${esc(ctx, post.name)}</strong><small>Local demo note${post.status === 'hidden' ? ' · hidden by admin' : ''}</small></div></div>
    <div class="cw-note-actions"><button type="button" data-community-action="post-heart" data-id="${esc(ctx, post.id)}" aria-pressed="${loved}" aria-label="${loved ? 'Remove' : 'Add'} appreciation" ${post.status === 'hidden' ? 'disabled' : ''}><span aria-hidden="true">${loved ? '♥' : '♡'}</span> ${list(post.hearts).length} <span>Appreciate</span></button><button type="button" data-community-action="post-reply" data-id="${esc(ctx, post.id)}" ${post.status === 'hidden' ? 'disabled' : ''}>${list(post.replies).length ? list(post.replies).length + ' replies' : 'Reply'} ↗</button>${own ? `<button type="button" data-community-action="post-delete" data-id="${esc(ctx, post.id)}" class="cw-delete">Delete</button>` : ''}</div>
    ${list(post.replies).length ? `<div class="cw-replies">${list(post.replies).map(reply => `<p><strong>${esc(ctx, reply.name)}</strong><span>${esc(ctx, reply.body)}</span></p>`).join('')}</div>` : ''}
  </article>`;
}

function communityWall(ctx) {
  const s = state(ctx), posts = list(s.posts).filter(post => post.status === 'published' || post.userId === s.profile?.id);
  return `<section class="cw-section" id="community-wall" aria-labelledby="wall-title">
    <header class="cw-heading"><div><p class="eyebrow">OUR LITTLE CORNER OF THE INTERNET</p><h2 id="wall-title">The adda wall.<br><em>Pull up a chair.</em></h2></div><p>A hello, a question, a small happy moment. It’s the little things that make a place feel like ours.</p></header>
    <div class="cw-layout"><aside class="cw-welcome"><figure><img src="assets/reference-peacocks.webp" alt="Your reference artwork of two painted peacocks and pink flowers" loading="lazy"><figcaption>Colour from home. Conversations from everywhere.</figcaption></figure><div class="cw-welcome-body"><span lang="bn">চলো, আড্ডা হোক!</span><h3>What’s your story?</h3><p>New to Japan? Missing your favourite fuchka? Found a great study spot? There’s a conversation waiting.</p><button class="btn btn-primary" data-community-action="post-compose">Leave a little note <span aria-hidden="true">↗</span></button><small>Interactive demo. Notes and replies stay in this browser; they are not shared with other people.</small></div></aside>
    <div class="cw-board"><div class="cw-filters" role="group" aria-label="Community note categories">${Object.entries({all: 'All notes', ...postCategories}).map(([key, label]) => `<button type="button" data-community-action="post-filter" data-filter="${key}" class="${wallFilter === key ? 'active' : ''}" aria-pressed="${wallFilter === key}">${label}</button>`).join('')}</div><p class="cw-results" id="wall-results" aria-live="polite">${posts.length} ${posts.length === 1 ? 'note' : 'notes'} on this device</p><div class="cw-note-grid" id="wall-notes">${posts.map(post => wallPost(ctx, post)).join('')}</div>
    <div class="cw-first-note" id="wall-empty" ${posts.length ? 'hidden' : ''}><img src="assets/rickshaw-flower.svg" alt="" aria-hidden="true"><p class="eyebrow">EVERY FRIENDSHIP STARTS SOMEWHERE</p><h3 id="wall-empty-title">Yours could be the first hello.</h3><p>Try one of these conversation starters.</p><div class="cw-prompts"><button data-community-action="post-compose" data-category="introduction">“A little about me…” <span>Introduce yourself ↗</span></button><button data-community-action="post-compose" data-category="question">“Does anyone know…” <span>Ask the community ↗</span></button><button data-community-action="post-compose" data-category="moment">“Today felt like home…” <span>Share a moment ↗</span></button></div></div></div></div>
  </section>`;
}

function communityCorner(ctx, p) {
  const count = list(state(ctx).posts).filter(post => post.userId === p.id).length;
  return `<section class="cw-profile-corner"><img src="assets/reference-flowers.webp" alt="Hand-painted red flower from your artwork references" loading="lazy"><div><p class="eyebrow">A COMMUNITY IS MADE OF LITTLE HELLOS</p><h3>Leave your mark.</h3><p>${count ? `You’ve left ${count} ${count === 1 ? 'note' : 'notes'} on the local adda wall.` : 'Share an introduction, ask a question, or celebrate a little moment on the adda wall.'}</p><a href="#/community" class="btn btn-secondary">Visit the adda wall ↗</a></div></section>`;
}

export function renderCommunity(ctx, alumniOnly = false) {
  const members = publicMembers(ctx).filter(m => !alumniOnly || memberType(m) === 'alumni');
  return `<main class="page-container community-page">
    <header class="page-heading community-heading"><div><p class="eyebrow">${alumniOnly ? 'ONCE A PART. ALWAYS A PART.' : 'ROOTS IN BANGLADESH. CONNECTIONS EVERYWHERE.'}</p><h1>${alumniOnly ? 'Our alumni.<br><em>Our next chapter.</em>' : 'Find your people.<br><em>Grow together.</em>'}</h1><p>${alumniOnly ? 'Meet the graduates carrying our community into new cities, careers, and possibilities.' : 'Students, alumni, and friends—bringing their stories, skills, and a little piece of home.'}</p></div><div class="community-heading-note"><span class="community-rosette" aria-hidden="true">✳</span><p>Different paths.<br><strong>One community.</strong></p></div></header>
    <div class="community-intro-strip"><p><strong>A directory built on choice.</strong> Members decide whether their profile appears here. Contact details stay private.</p><a class="btn btn-secondary" href="#/join">Join the community <span aria-hidden="true">↗</span></a></div>
    ${!alumniOnly ? communityWall(ctx) : ''}
    <div class="cw-directory-title"><p class="eyebrow">FAMILIAR FACES. NEW POSSIBILITIES.</p><h2>${alumniOnly ? 'Meet the alumni.' : 'Find your people.'}</h2></div>
    <div class="directory-sample-notice"><span class="sample-label">Interactive demo</span> These sample profiles show how the member directory works. Requests stay on this device.</div>
    <section aria-label="Find community members">
      <div class="toolbar directory-toolbar"><label class="directory-search"><span class="sr-only">Search members by name, university, skill, employer, or city</span><input class="search-input" type="search" id="community-search" placeholder="Search a name, skill, university, or city…" value="${esc(ctx, directoryState.query)}"><span aria-hidden="true">⌕</span></label><div class="directory-filters" role="group" aria-label="Member filters">${!alumniOnly ? ['all', 'student', 'alumni', 'community'].map(type => `<button class="filter-chip ${directoryState.type === type ? 'active' : ''}" data-community-action="filter" data-filter="${type}" aria-pressed="${directoryState.type === type}">${type === 'all' ? 'Everyone' : types[type]}</button>`).join('') : ''}<button class="filter-chip ${directoryState.mentors ? 'active' : ''}" data-community-action="mentors" aria-pressed="${directoryState.mentors}">Open to mentoring</button></div></div>
      <div class="directory-results-line"><p id="community-results" aria-live="polite">${members.length} ${members.length === 1 ? 'person' : 'people'} to discover</p><span>Community, beyond campus</span></div>
      <div class="member-grid community-grid" id="community-grid" data-alumni-only="${alumniOnly}">${members.map(m => memberCard(ctx, m)).join('')}</div>
      <div class="empty-state directory-empty" id="community-empty" hidden><span aria-hidden="true">⌕</span><h3>No people found</h3><p>Try a different name, skill, or city, or clear the filters.</p><button class="btn btn-secondary" data-community-action="clear-filters">Clear filters</button></div>
    </section>
    <section class="community-callout"><div><p class="eyebrow">A LITTLE GUIDANCE GOES A LONG WAY</p><h2>Your experience could be<br>someone’s beginning.</h2><p>Share what you’ve learned. Make your profile available for mentorship.</p></div><a class="btn btn-primary" href="${state(ctx).profile ? '#/profile' : '#/join'}">Become a mentor <span aria-hidden="true">↗</span></a></section>
  </main>`;
}

export function renderMember(ctx, id) {
  const m = publicMembers(ctx).find(item => item.id === id);
  if (!m) return `<main class="page-container"><div class="empty-state"><h1>This profile isn’t available</h1><p>It may be private or awaiting approval.</p><a class="btn btn-primary" href="#/community">Explore the community</a></div></main>`;
  const own = state(ctx).profile?.id === m.id;
  return `<main class="page-container member-detail-page"><a class="back-link" href="#/community">← Back to community</a><div class="profile-cover"><span class="cover-circle"></span><span class="cover-art" aria-hidden="true">✳</span><p lang="bn">শেকড়ে বাংলাদেশ, স্বপ্নে পৃথিবী</p></div><section class="member-detail-header">${avatar(ctx, m, true)}<div><div class="member-title-line"><span class="badge badge-soft">${typeLabel(m)}</span><span class="sample-label">Demo profile</span></div><h1>${esc(ctx, m.name)}</h1>${m.nameBn ? `<p class="member-bangla" lang="bn">${esc(ctx, m.nameBn)}</p>` : ''}<p>${esc(ctx, [m.jobTitle || m.major, m.employer || m.university, m.city].filter(Boolean).join(' · '))}</p></div><div class="member-detail-actions">${own ? '<a class="btn btn-primary" href="#/profile">Edit my profile</a>' : `<button class="btn btn-primary" data-community-action="connect" data-member-id="${esc(ctx, m.id)}">Say hello <span aria-hidden="true">↗</span></button>${m.mentor ? `<button class="btn btn-secondary" data-community-action="mentor" data-member-id="${esc(ctx, m.id)}">Request mentorship</button>` : ''}`}</div></section>
    <div class="member-detail-layout"><section class="panel member-about"><p class="eyebrow">A LITTLE ABOUT ME</p><h2>My story</h2><p class="bio-text">${esc(ctx, m.bio || 'This member is still writing their story.')}</p><h3>What I bring</h3><div class="member-skills member-skills-large">${list(m.skills).length ? list(m.skills).map(skill => `<span>${esc(ctx, skill)}</span>`).join('') : '<p>Skills coming soon.</p>'}</div>${m.mentor ? '<div class="mentor-callout"><span aria-hidden="true">↗</span><div><strong>Open to mentoring</strong><p>Happy to share experiences, exchange ideas, and help someone take their next step.</p></div></div>' : ''}</section><aside class="panel member-facts"><p class="eyebrow">THE DETAILS</p>${fact(ctx, 'Education', m.university)}${fact(ctx, 'Field of study', m.major)}${fact(ctx, 'Graduation', m.graduation)}${fact(ctx, 'Work', m.employer)}${fact(ctx, 'Role', m.jobTitle)}${fact(ctx, 'Based in', m.city)}<p class="privacy-note">Contact information is private. This is an illustrative profile in the local demo.</p></aside></div>
  </main>`;
}

function fact(ctx, label, value) { return value ? `<div class="member-fact"><span>${label}</span><strong>${esc(ctx, value)}</strong></div>` : ''; }
function input(ctx, label, name, value = '', extra = '', type = 'text') { return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(ctx, value)}" ${extra}></label>`; }
function profileFields(ctx, profile = {}) {
  return `<div class="form-section-heading"><span>01</span><div><h3>Your introduction</h3><p>Tell the community a little about yourself.</p></div></div><div class="form-grid">${input(ctx, 'Full name *', 'name', profile.name, 'required maxlength="80" autocomplete="name"')}${input(ctx, 'Name in Bangla', 'nameBn', profile.nameBn, 'maxlength="80" lang="bn"')}<label class="field"><span>I’m joining as *</span><select name="type" required>${Object.entries(types).map(([value, text]) => `<option value="${value}" ${memberType(profile) === value ? 'selected' : ''}>${text}</option>`).join('')}</select></label>${input(ctx, 'Based in', 'city', profile.city, 'maxlength="80" placeholder="e.g. Tokyo, Japan"')}${input(ctx, 'Email · private (optional in demo)', 'email', profile.email, 'maxlength="160" autocomplete="email"', 'email')}<label class="field form-span-2"><span>My story</span><textarea name="bio" rows="4" maxlength="1000" placeholder="Your interests, your journey, and what brings you here…">${esc(ctx, profile.bio)}</textarea></label></div>
    <div class="form-section-heading"><span>02</span><div><h3>Study & work</h3><p>Good conversations often start with something in common.</p></div></div><div class="form-grid">${input(ctx, 'University or school', 'university', profile.university, 'maxlength="140" placeholder="e.g. Tokyo International University"')}${input(ctx, 'Field of study', 'major', profile.major, 'maxlength="100"')}${input(ctx, 'Graduation year', 'graduation', profile.graduation, 'min="1950" max="2100" inputmode="numeric"', 'number')}${input(ctx, 'Company or organisation', 'employer', profile.employer, 'maxlength="140"')}${input(ctx, 'Job title', 'jobTitle', profile.jobTitle, 'maxlength="100"')}${input(ctx, 'Skills · separated by commas', 'skills', list(profile.skills).join(', '), 'maxlength="300" placeholder="Design, marketing, research"')}</div>
    <div class="form-section-heading"><span>03</span><div><h3>Your choice. Your privacy.</h3><p>You’re in control of how you appear in the community.</p></div></div><div class="profile-preferences"><label class="checkbox-field"><input type="checkbox" name="directoryVisible" ${profile.directoryVisible ? 'checked' : ''}><span><strong>Show my profile in the community directory</strong><small>Share your name, bio, education, work, city, and skills. Your email stays private.</small></span></label><label class="checkbox-field"><input type="checkbox" name="mentor" ${profile.mentor ? 'checked' : ''}><span><strong>I’m open to mentoring</strong><small>Let community members know you’re happy to share your experience.</small></span></label></div>`;
}

export function renderJoin(ctx) {
  if (state(ctx).profile) return `<main class="page-container"><div class="empty-state"><p class="eyebrow">YOU’RE ALREADY HERE</p><h1>Welcome back, ${esc(ctx, state(ctx).profile.name.split(' ')[0])}.</h1><p>Your demo profile is ready. Make yourself at home.</p><a class="btn btn-primary" href="#/profile">Open my dashboard</a><a class="btn btn-secondary" href="#/community">Meet the community</a></div></main>`;
  return `<main class="page-container join-page"><header class="page-heading"><p class="eyebrow">THERE’S A PLACE FOR YOU HERE</p><h1>Let’s make it<br><em>feel like home.</em></h1><p>Join a community of students, alumni, and friends connected by Bangladesh and a shared future.</p></header><div class="join-layout"><form class="panel profile-form" id="community-join-form"><div class="demo-form-note"><span class="sample-label">Local demo</span><p>Firebase sign-in is not connected. This creates a demo profile in this browser only. It won’t create a live account or send any messages.</p></div>${profileFields(ctx, { type: 'student', directoryVisible: false, mentor: false })}<div class="form-submit-row"><button class="btn btn-primary" type="submit">Create a demo profile <span aria-hidden="true">↗</span></button><span>* Required fields</span></div><p class="form-error" role="alert" hidden></p></form><aside class="join-aside"><div class="join-art" aria-hidden="true"><span>✳</span><p lang="bn">একসাথে<br>আরও দূর</p></div><h2>Your next connection<br>starts here.</h2><p>Find people who understand your journey, discover events, and give back in your own way.</p><ul class="join-benefits"><li>Build your community profile</li><li>Keep event tickets in one place</li><li>Manage food orders</li><li>Connect with alumni and mentors</li></ul><p class="privacy-note">Only opt-in profiles appear in the directory. You can edit or remove your local demo profile at any time.</p></aside></div></main>`;
}

function personalRecords(ctx, collection) { const s = state(ctx); return list(s[collection]).filter(item => item.userId === s.profile?.id).sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0)); }
function statusBadge(ctx, status) { return `<span class="badge status-${esc(ctx, status || 'pending')}">${esc(ctx, String(status || 'pending').replaceAll('_', ' '))}</span>`; }
function eventFor(ctx, id) { return list(state(ctx).events).find(event => event.id === id); }
function shortDate(ctx, value) { try { return value ? ctx.formatDate(value) : 'Date to be announced'; } catch { return 'Date to be announced'; } }
function ticketCard(ctx, ticket) {
  const event = eventFor(ctx, ticket.eventId);
  const active = !['cancelled', 'refunded'].includes(ticket.status);
  return `<article class="ticket-card personal-ticket"><div class="ticket-card-top"><span class="eyebrow">EVENT PASS</span>${statusBadge(ctx, ticket.status)}</div><h3>${esc(ctx, event?.title || 'Community event')}</h3><p>${esc(ctx, shortDate(ctx, event?.startAt || event?.startsAt || event?.date))}</p><p class="ticket-reference">${esc(ctx, ticket.name || state(ctx).profile?.name)} · ${esc(ctx, ticket.id)}</p><div class="ticket-card-actions">${active ? `<button class="btn btn-primary btn-small" data-community-action="ticket-qr" data-id="${esc(ctx, ticket.id)}">View ticket & QR</button>` : ''}${active && !ticket.checkedInAt ? `<button class="text-button" data-community-action="cancel-ticket" data-id="${esc(ctx, ticket.id)}">Cancel registration</button>` : ''}${ticket.checkedInAt ? '<span class="checked-in-label">✓ Checked in</span>' : ''}</div><span class="sample-label">Demo ticket</span></article>`;
}
function orderCard(ctx, order) {
  const event = eventFor(ctx, order.eventId);
  return `<article class="panel personal-order"><div class="ticket-card-top"><div><p class="eyebrow">FOOD ORDER</p><h3>${esc(ctx, event?.title || 'Community event')}</h3></div>${statusBadge(ctx, order.status)}</div><ul class="personal-order-items">${list(order.items).map(item => `<li><span>${esc(ctx, item.qty)} × ${esc(ctx, item.name)}</span><strong>${ctx.money((Number(item.price) || 0) * (Number(item.qty) || 0))}</strong></li>`).join('')}</ul><div class="order-summary-line"><span>Order total</span><strong>${ctx.money(order.total || 0)}</strong></div><p class="order-pickup">Pickup: ${esc(ctx, order.pickup || 'See event details')} · Payment: ${esc(ctx, String(order.paymentStatus || 'unpaid').replaceAll('_', ' '))}</p><div class="ticket-card-actions">${!['cancelled', 'collected'].includes(order.status) ? `<button class="btn btn-primary btn-small" data-community-action="order-qr" data-id="${esc(ctx, order.id)}">View pickup QR</button>` : ''}${['pending', 'confirmed', 'placed', 'new'].includes(order.status) && order.paymentStatus !== 'paid' ? `<button class="text-button" data-community-action="cancel-order" data-id="${esc(ctx, order.id)}">Cancel order</button>` : ''}</div><span class="sample-label">Demo order · ${esc(ctx, order.id)}</span></article>`;
}
function empty(ctx, title, copy, label, href) { return `<div class="empty-state"><span class="empty-flower" aria-hidden="true">✳</span><h3>${title}</h3><p>${copy}</p>${label ? `<a class="btn btn-secondary" href="${href}">${label}</a>` : ''}</div>`; }
function profileOverview(ctx, p) {
  const tickets = personalRecords(ctx, 'tickets');
  const orders = personalRecords(ctx, 'orders');
  const messages = list(state(ctx).messages).filter(m => (m.fromUserId === p.id || m.userId === p.id) && ['connection', 'mentorship'].includes(m.type)).sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
  const complete = ['name', 'bio', 'city', 'university'].filter(key => Boolean(p[key])).length + (list(p.skills).length > 0 ? 1 : 0);
  return `<div class="dashboard-welcome"><p class="eyebrow">YOUR COMMUNITY, IN ONE PLACE</p><h2>Hello, ${esc(ctx, p.name.split(' ')[0])}.</h2><p>Good to have you here. Your next gathering is just around the corner.</p></div><div class="profile-stat-grid"><button class="panel profile-stat" data-community-action="profile-tab" data-tab="tickets"><strong>${tickets.filter(t => t.status !== 'cancelled').length}</strong><span>Event tickets <span aria-hidden="true">↗</span></span></button><button class="panel profile-stat" data-community-action="profile-tab" data-tab="orders"><strong>${orders.filter(o => o.status !== 'cancelled').length}</strong><span>Food orders <span aria-hidden="true">↗</span></span></button><div class="panel profile-stat"><strong>${messages.length}</strong><span>Connection requests</span></div></div><section class="panel profile-completion"><div><p class="eyebrow">MAKE YOURSELF KNOWN</p><h3>Your story is ${complete * 20}% complete.</h3><p>Add a bio, your city, education, and skills so people can find common ground.</p></div><div class="completion-bar" role="progressbar" aria-label="Profile completeness" aria-valuenow="${complete * 20}" aria-valuemin="0" aria-valuemax="100"><span style="width:${complete * 20}%"></span></div><button class="btn btn-secondary" data-community-action="profile-tab" data-tab="edit">Edit my profile</button></section><div class="section-title-row"><h3>My latest tickets</h3><button class="text-button" data-community-action="profile-tab" data-tab="tickets">See all →</button></div>${tickets.length ? `<div class="personal-tickets-grid">${tickets.slice(0, 2).map(ticket => ticketCard(ctx, ticket)).join('')}</div>` : empty(ctx, 'A good gathering is waiting.', 'Register for a community event to find your ticket here.', 'Explore events', '#/events')}<section class="panel connection-history"><div class="section-title-row"><h3>Connection requests</h3><span class="sample-label">Local demo only</span></div>${messages.length ? `<ul>${messages.slice(0, 5).map(m => `<li><div><strong>${esc(ctx, m.type === 'mentorship' ? 'Mentorship request' : 'Connection request')}</strong><p>To ${esc(ctx, m.toName || publicMembers(ctx).find(person => person.id === m.toUserId)?.name || 'a community member')}</p></div><span class="badge badge-soft">Saved locally</span></li>`).join('')}</ul>` : '<p>Your saved connection and mentorship requests will appear here.</p>'}</section>`;
}
function profilePrivacy(ctx, p) {
  return `<section class="panel privacy-panel"><p class="eyebrow">YOU’RE IN CONTROL</p><h2>Privacy & your data</h2><p>This prototype stores your demo profile and activity in this browser. It does not authenticate with Firebase or send messages to community members.</p><div class="privacy-setting"><div><h3>Community directory</h3><p>${p.directoryVisible ? (p.status === 'approved' ? 'Your demo profile is visible in the local member directory.' : 'Your directory listing is awaiting membership approval.') : 'Your profile is hidden from the member directory.'} Email addresses never appear on public profiles.</p></div><button class="btn btn-secondary" data-community-action="toggle-visibility">${p.directoryVisible ? 'Hide my profile' : 'Show my profile'}</button></div><div class="privacy-setting"><div><h3>Download my demo data</h3><p>Export your profile, tickets, orders, and connection requests as a JSON file.</p></div><button class="btn btn-secondary" data-community-action="export-data">Download data</button></div><div class="privacy-setting danger-setting"><div><h3>Delete my demo profile</h3><p>Remove your local profile. Existing event, order, and request records stay in the demo until the demo is reset.</p></div><button class="btn btn-danger" data-community-action="delete-profile">Delete profile</button></div></section>`;
}

export function renderProfile(ctx) {
  const p = state(ctx).profile;
  if (!p) return `<main class="page-container"><div class="empty-state"><p class="eyebrow">YOUR OWN CORNER OF THE COMMUNITY</p><h1>Make yourself at home.</h1><p>Create a demo profile to manage event tickets, food orders, and your community presence. Firebase sign-in is not connected yet.</p><a class="btn btn-primary" href="#/join">Create a demo profile</a><a class="btn btn-secondary" href="#/community">Explore the community</a></div></main>`;
  const tabs = [['overview', 'Overview'], ['tickets', 'My tickets'], ['orders', 'Food orders'], ['edit', 'Edit profile'], ['privacy', 'Privacy & data']];
  let content = '';
  if (profileTab === 'overview') content = profileOverview(ctx, p) + communityCorner(ctx, p);
  if (profileTab === 'tickets') { const records = personalRecords(ctx, 'tickets'); content = `<div class="section-title-row"><div><p class="eyebrow">MEMORIES START HERE</p><h2>My tickets</h2></div><a class="btn btn-secondary" href="#/events">Explore events</a></div>${records.length ? `<div class="personal-tickets-grid">${records.map(t => ticketCard(ctx, t)).join('')}</div>` : empty(ctx, 'Your next memory awaits.', 'Tickets will appear here after you register for an event.', 'Find an event', '#/events')}`; }
  if (profileTab === 'orders') { const records = personalRecords(ctx, 'orders'); content = `<div class="section-title-row"><div><p class="eyebrow">A TASTE OF HOME</p><h2>My food orders</h2></div><a class="btn btn-secondary" href="#/events">Browse events</a></div>${records.length ? `<div class="personal-orders-grid">${records.map(o => orderCard(ctx, o)).join('')}</div>` : empty(ctx, 'Come hungry. Leave happy.', 'Order from an event’s food menu and manage pickup here.', 'Explore event menus', '#/events')}`; }
  if (profileTab === 'edit') content = `<form class="panel profile-form" id="community-edit-form"><p class="eyebrow">TELL YOUR STORY</p><h2>Edit my profile</h2>${profileFields(ctx, p)}<div class="form-submit-row"><button class="btn btn-primary" type="submit">Save profile</button><span>Saved on this device only</span></div><p class="form-error" role="alert" hidden></p></form>`;
  if (profileTab === 'privacy') content = profilePrivacy(ctx, p);
  return `<main class="page-container account-page"><div class="account-heading"><div><p class="eyebrow">MY BSS</p><h1>Your community dashboard.</h1></div><div class="member-title-line">${statusBadge(ctx, p.status || 'pending')}<span class="sample-label">Local demo profile</span></div></div><div class="profile-layout"><aside class="profile-sidebar"><div class="profile-sidebar-identity">${avatar(ctx, p, true)}<h2>${esc(ctx, p.name)}</h2><p>${typeLabel(p)}${p.city ? ` · ${esc(ctx, p.city)}` : ''}</p><span class="badge badge-soft">${p.directoryVisible ? (p.status === 'approved' ? 'Visible in directory' : 'Awaiting approval') : 'Private profile'}</span></div><nav class="profile-tabs" aria-label="Profile sections">${tabs.map(([id, label]) => `<button data-community-action="profile-tab" data-tab="${id}" class="${profileTab === id ? 'active' : ''}" ${profileTab === id ? 'aria-current="page"' : ''}>${label}<span aria-hidden="true">↗</span></button>`).join('')}</nav><p class="privacy-note">A demo made for exploring.<br>Your data stays on this device.</p></aside><div class="profile-main">${content}</div></div></main>`;
}

function applyDirectoryFilters() {
  const grid = document.getElementById('community-grid');
  if (!grid) return;
  const alumniOnly = grid.dataset.alumniOnly === 'true';
  let count = 0;
  grid.querySelectorAll('[data-member-search]').forEach(card => {
    const visible = card.dataset.memberSearch.includes(directoryState.query.trim().toLowerCase()) && (alumniOnly || directoryState.type === 'all' || card.dataset.memberType === directoryState.type) && (!directoryState.mentors || card.dataset.memberMentor === 'true');
    card.hidden = !visible;
    if (visible) count++;
  });
  const results = document.getElementById('community-results');
  if (results) results.textContent = `${count} ${count === 1 ? 'person' : 'people'} to discover`;
  const empty = document.getElementById('community-empty');
  if (empty) empty.hidden = count > 0;
  document.querySelectorAll('[data-community-action="filter"]').forEach(btn => { const on = btn.dataset.filter === directoryState.type; btn.classList.toggle('active', on); btn.setAttribute('aria-pressed', String(on)); });
  const mentor = document.querySelector('[data-community-action="mentors"]');
  if (mentor) { mentor.classList.toggle('active', directoryState.mentors); mentor.setAttribute('aria-pressed', String(directoryState.mentors)); }
}
function applyWallFilters() {
  let count = 0;
  const notes = document.querySelectorAll('[data-wall-category]');
  notes.forEach(note => { const visible = wallFilter === 'all' || note.dataset.wallCategory === wallFilter; note.hidden = !visible; if (visible) count++; });
  document.querySelectorAll('[data-community-action="post-filter"]').forEach(button => { const active = button.dataset.filter === wallFilter; button.classList.toggle('active', active); button.setAttribute('aria-pressed', String(active)); });
  const countEl = document.getElementById('wall-results');
  if (countEl) countEl.textContent = `${count} ${count === 1 ? 'note' : 'notes'}${wallFilter !== 'all' ? ' in this category' : ' on this device'}`;
  const empty = document.getElementById('wall-empty');
  if (empty) empty.hidden = count > 0;
  const emptyTitle = document.getElementById('wall-empty-title');
  if (emptyTitle) emptyTitle.textContent = notes.length ? 'Start a new conversation here.' : 'Yours could be the first hello.';
}
function requireWallProfile(ctx) {
  if (state(ctx).profile) return true;
  ctx.modal('Your hello starts with a name', '<p>Create a local demo profile to leave notes, appreciate a post, or reply. Your profile and contributions stay on this device.</p><div class="modal-actions"><a id="wall-join" href="#/join" class="btn btn-primary">Create a demo profile ↗</a></div>', () => document.getElementById('wall-join')?.addEventListener('click', () => ctx.closeModal()));
  return false;
}
function composePost(ctx, category = 'introduction') {
  if (!requireWallProfile(ctx)) return;
  ctx.modal('Leave a little note', `<form id="community-post-form"><p>A good adda starts with a little sharing.</p><label class="field"><span>What would you like to share?</span><select name="category">${Object.entries(postCategories).map(([key, label]) => `<option value="${key}" ${key === category ? 'selected' : ''}>${label}</option>`).join('')}</select></label><label class="field"><span>Your note *</span><textarea name="body" required maxlength="600" rows="5" placeholder="A little about me…"></textarea></label><p class="cw-compose-help">Share kindly. Your name appears beside your note. This saves a local demo note, visible only in this browser.</p><div class="modal-actions"><button type="submit" class="btn btn-primary">Pin my demo note ↗</button></div><p class="form-error" role="alert" hidden></p></form>`, () => {
    document.getElementById('community-post-form')?.addEventListener('submit', event => { event.preventDefault(); const form = event.currentTarget, data = new FormData(form); try { ctx.store.createCommunityPost({category: data.get('category'), body: data.get('body')}); wallFilter = 'all'; ctx.closeModal(); ctx.render(); document.getElementById('community-wall')?.scrollIntoView({block: 'start'}); ctx.toast('Your note is pinned to this device’s adda wall.'); } catch (error) { showFormError(form, error); } });
  });
}
function replyToPost(ctx, id) {
  if (!requireWallProfile(ctx)) return;
  const post = list(state(ctx).posts).find(item => item.id === id);
  if (!post) return;
  ctx.modal('Keep the conversation going', `<form id="community-reply-form"><blockquote class="cw-reply-context">${esc(ctx, post.body)}</blockquote><label class="field"><span>Your reply *</span><textarea name="body" rows="4" maxlength="300" required placeholder="I’d love to add…"></textarea></label><p class="cw-compose-help">Replies stay in this browser. No message will be sent.</p><div class="modal-actions"><button class="btn btn-primary" type="submit">Save demo reply ↗</button></div><p class="form-error" role="alert" hidden></p></form>`, () => { document.getElementById('community-reply-form')?.addEventListener('submit', event => { event.preventDefault(); const form = event.currentTarget; try { ctx.store.replyToCommunityPost(id, new FormData(form).get('body')); ctx.closeModal(); ctx.render(); ctx.toast('Your reply was saved on this device.'); } catch (error) { showFormError(form, error); } }); });
}
function readProfile(form, old = {}) {
  const data = new FormData(form);
  const fields = ['name', 'nameBn', 'type', 'city', 'email', 'bio', 'university', 'major', 'graduation', 'employer', 'jobTitle'];
  const p = { ...old, id: old.id || 'me', status: old.status || 'pending', isDemo: true };
  fields.forEach(key => { p[key] = String(data.get(key) || '').trim(); });
  p.skills = [...new Set(String(data.get('skills') || '').split(',').map(s => s.trim()).filter(Boolean))].slice(0, 15);
  p.directoryVisible = data.get('directoryVisible') === 'on';
  p.mentor = data.get('mentor') === 'on';
  p.updatedAt = new Date().toISOString();
  p.createdAt = old.createdAt || p.updatedAt;
  return p;
}
function requestConnection(ctx, memberId, mentorship) {
  const s = state(ctx), m = publicMembers(ctx).find(item => item.id === memberId);
  if (!m) return;
  if (!s.profile) { ctx.modal('Start with your profile', `<p>Create a demo profile to explore connection and mentorship requests. Requests are saved on this device only.</p><div class="modal-actions"><a href="#/join" class="btn btn-primary" id="connection-join">Create a demo profile</a></div>`, () => { document.getElementById('connection-join')?.addEventListener('click', () => ctx.closeModal()); }); return; }
  ctx.modal(mentorship ? 'A new perspective starts here' : `Say hello to ${m.name.split(' ')[0]}`, `<form id="community-message-form"><p>${mentorship ? 'Introduce yourself and share what you’d like guidance with.' : 'Tell them a little about yourself and why you’d like to connect.'}</p><div class="demo-form-note"><span class="sample-label">Demo request</span><p>This request is saved locally. No email or message will be sent.</p></div><label class="field"><span>Your message *</span><textarea name="message" required maxlength="1500" rows="5" placeholder="Hi ${esc(ctx, m.name.split(' ')[0])}, I’m…"></textarea></label><div class="modal-actions"><button class="btn btn-primary" type="submit">Save demo request</button></div><p class="form-error" role="alert" hidden></p></form>`, () => {
    document.getElementById('community-message-form')?.addEventListener('submit', async event => {
      event.preventDefault(); const form = event.currentTarget; const message = new FormData(form).get('message').trim(); if (!message) return;
      try { await ctx.store.saveRecord('messages', { id: `msg_${crypto.randomUUID()}`, type: mentorship ? 'mentorship' : 'connection', fromUserId: s.profile.id, userId: s.profile.id, toUserId: m.id, toName: m.name, name: s.profile.name, subject: `${mentorship ? 'Mentorship' : 'Connection'} request to ${m.name}`, message, status: 'saved_locally', isDemo: true, createdAt: new Date().toISOString() }); ctx.closeModal(); ctx.toast('Demo request saved on this device. No message was sent.'); } catch (error) { showFormError(form, error); }
    });
  });
}
function showFormError(form, error) { const el = form.querySelector('.form-error'); if (el) { el.textContent = error.message || 'Something went wrong. Please try again.'; el.hidden = false; } }
function confirmAction(ctx, title, copy, label, action) { ctx.modal(title, `<p>${copy}</p><div class="modal-actions"><button class="btn btn-secondary" id="community-confirm-back">Keep it</button><button class="btn btn-danger" id="community-confirm-action">${label}</button></div>`, () => { document.getElementById('community-confirm-back')?.addEventListener('click', () => ctx.closeModal()); document.getElementById('community-confirm-action')?.addEventListener('click', async () => { try { await action(); ctx.closeModal(); ctx.render(); } catch (error) { ctx.toast(error.message || 'Unable to complete this action.'); } }); }); }

export function mountCommunity(ctx) {
  applyDirectoryFilters();
  applyWallFilters();
  const wallRequested = Boolean(globalThis.location?.hash?.includes('wall=1'));
  if (wallRequested && !wallDeepLinkHandled) { const wall = document.getElementById('community-wall'), heading = document.getElementById('wall-title'); wall?.scrollIntoView?.({block: 'start'}); heading?.setAttribute('tabindex', '-1'); heading?.focus?.({preventScroll: true}); }
  wallDeepLinkHandled = wallRequested;
  document.getElementById('community-search')?.addEventListener('input', event => { directoryState.query = event.target.value; applyDirectoryFilters(); });
  for (const formId of ['community-join-form', 'community-edit-form']) {
    document.getElementById(formId)?.addEventListener('submit', async event => {
      event.preventDefault(); const form = event.currentTarget;
      const profile = readProfile(form, formId === 'community-edit-form' ? state(ctx).profile : {});
      if (!profile.name) { showFormError(form, new Error('Please enter your name.')); return; }
      const submit = form.querySelector('[type="submit"]'); submit.disabled = true;
      try { await ctx.store.saveProfile(profile); profileTab = 'overview'; ctx.toast(formId === 'community-join-form' ? 'Your demo profile is ready. Welcome to BSS.' : 'Your profile has been saved.'); if (formId === 'community-join-form') ctx.navigate('/profile'); else ctx.render(); } catch (error) { showFormError(form, error); submit.disabled = false; }
    });
  }
  document.querySelectorAll('#app [data-community-action]').forEach(button => button.addEventListener('click', async () => {
    const action = button.dataset.communityAction, s = state(ctx);
    if (action === 'post-filter') { wallFilter = button.dataset.filter; applyWallFilters(); }
    if (action === 'post-compose') composePost(ctx, button.dataset.category);
    if (action === 'post-reply') replyToPost(ctx, button.dataset.id);
    if (action === 'post-heart' && requireWallProfile(ctx)) { try { ctx.store.togglePostHeart(button.dataset.id); ctx.render(); } catch (error) { ctx.toast(error.message); } }
    if (action === 'post-delete') confirmAction(ctx, 'Remove your note?', 'This also removes its replies from this device’s adda wall. This cannot be undone.', 'Delete my note', () => { ctx.store.deleteCommunityPost(button.dataset.id); ctx.toast('Your note was removed.'); });
    if (action === 'filter') { directoryState.type = button.dataset.filter; applyDirectoryFilters(); }
    if (action === 'mentors') { directoryState.mentors = !directoryState.mentors; applyDirectoryFilters(); }
    if (action === 'clear-filters') { directoryState.query = ''; directoryState.type = 'all'; directoryState.mentors = false; const search = document.getElementById('community-search'); if (search) search.value = ''; applyDirectoryFilters(); }
    if (action === 'profile-tab') { profileTab = button.dataset.tab; ctx.render(); }
    if (action === 'connect' || action === 'mentor') requestConnection(ctx, button.dataset.memberId, action === 'mentor');
    if (action === 'ticket-qr') { const ticket = personalRecords(ctx, 'tickets').find(item => item.id === button.dataset.id); if (ticket) ctx.showTicket(ticket, 'event'); }
    if (action === 'order-qr') { const order = personalRecords(ctx, 'orders').find(item => item.id === button.dataset.id); if (order) ctx.showTicket(order, 'food'); }
    if (action === 'cancel-ticket') confirmAction(ctx, 'Cancel this registration?', 'Your demo ticket will become invalid and its place will be released.', 'Cancel registration', async () => { await ctx.store.cancelTicket(button.dataset.id); ctx.toast('Demo registration cancelled.'); });
    if (action === 'cancel-order') confirmAction(ctx, 'Cancel this food order?', 'Your demo order will be cancelled. No real payment or refund is involved.', 'Cancel order', async () => { await ctx.store.cancelOrder(button.dataset.id); ctx.toast('Demo food order cancelled.'); });
    if (action === 'toggle-visibility' && s.profile) { try { await ctx.store.saveProfile({ ...s.profile, directoryVisible: !s.profile.directoryVisible }); ctx.toast(s.profile.directoryVisible ? 'Your profile is now hidden.' : (s.profile.status === 'approved' ? 'Your profile is now visible in the demo directory.' : 'Directory opt-in saved. Your listing is awaiting membership approval.')); ctx.render(); } catch (error) { ctx.toast(error.message); } }
    if (action === 'export-data' && s.profile) {
      const payload = { exportedAt: new Date().toISOString(), demo: true, profile: s.profile, tickets: personalRecords(ctx, 'tickets'), orders: personalRecords(ctx, 'orders'), messages: list(s.messages).filter(m => m.fromUserId === s.profile.id || m.userId === s.profile.id), volunteerApplications: list(s.volunteers).filter(m => m.userId === s.profile.id), communityNotes: list(s.posts).filter(m => m.userId === s.profile.id) };
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'my-bss-demo-data.json'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); ctx.toast('Your demo data download is ready.');
    }
    if (action === 'delete-profile' && s.profile) confirmAction(ctx, 'Delete your demo profile?', 'This removes your profile and adda wall contributions from this browser and the directory. Existing ticket, food order, and request records remain in the local demo. Download your data first if you’d like a copy. This cannot be undone.', 'Delete my profile', async () => { await ctx.store.removeRecord('members', s.profile.id); profileTab = 'overview'; ctx.toast('Your demo profile has been deleted.'); });
  }));
}

